import{_ as d,o as r,c as a,ag as o}from"./chunks/framework.D2veAa-g.js";const u=JSON.parse('{"title":"架构师-备考 案例分析-基础与安全真题回顾","description":"","frontmatter":{"title":"架构师-备考 案例分析-基础与安全真题回顾"},"headers":[],"relativePath":"案例分析/基础与安全真题回顾.md","filePath":"案例分析/基础与安全真题回顾.md","lastUpdated":null}'),e={name:"案例分析/基础与安全真题回顾.md"};function h(n,t,s,l,i,b){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 位示图计算</li><li>[x] 死锁 4 必要条件（可破坏 vs 不可破坏）</li><li>[x] 进程状态转换（运行→就绪 vs 运行→阻塞）</li><li>[x] 实时调度算法（EDF/RM/LLF）</li><li>[x] 芯片温度等级 + ROM 类型</li><li>[x] 嵌入式系统架构与 M2M</li><li>[x] 奈奎斯特 / 香农定理 / 采样定理 ★</li><li>[x] OSI 7 层 + 网络设备对应</li><li>[x] 5 类安全服务 + 安全审计 4 要素</li><li>[x] GB17859 5 级 + 灾备 6 级</li><li>[x] 数据库三级模式 + 范式（1NF→4NF）</li><li>[x] 关系代数基本运算</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、计算机基础核心公式-★" tabindex="-1">一、计算机基础核心公式 ★ <a class="header-anchor" href="#一、计算机基础核心公式-★" aria-label="Permalink to &quot;一、计算机基础核心公式 ★&quot;">​</a></h3><h4 id="位示图计算" tabindex="-1">位示图计算 <a class="header-anchor" href="#位示图计算" aria-label="Permalink to &quot;位示图计算&quot;">​</a></h4><p>总页数 = 总容量 ÷ 页大小 → 位示图大小 = 总页数 bit ÷ 8 → Byte → KB。</p><blockquote><p>例：16 GB ÷ 4 KB = 2^22 页 → 2^22 bit = 2^19 Byte = <strong>512 KB</strong>。</p></blockquote><h4 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h4><p><strong>4 必要条件</strong>：互斥、请求保持、不可抢占、循环等待。</p><table tabindex="0"><thead><tr><th>破坏策略</th><th>是否可行</th></tr></thead><tbody><tr><td>破坏&quot;互斥&quot;</td><td><strong>不可行</strong>（临界资源本身必须互斥，是资源属性非策略能改）</td></tr><tr><td>破坏&quot;请求保持&quot;</td><td>可行（一次性分配）</td></tr><tr><td>破坏&quot;不可抢占&quot;</td><td>可行（抢占式分配）</td></tr><tr><td>破坏&quot;循环等待&quot;</td><td>可行（顺序编号分配）</td></tr></tbody></table><blockquote><p>避免死锁最小资源数：<strong>n × (k - 1) + 1</strong>（n 进程，每进程需 k 资源）。</p></blockquote><h4 id="进程状态转换" tabindex="-1">进程状态转换 <a class="header-anchor" href="#进程状态转换" aria-label="Permalink to &quot;进程状态转换&quot;">​</a></h4><table tabindex="0"><thead><tr><th>转换</th><th>触发事件</th></tr></thead><tbody><tr><td><strong>运行 → 就绪</strong></td><td>时间片用完 / 被更高优先级进程抢占</td></tr><tr><td><strong>运行 → 阻塞</strong></td><td>信号量 wait() / 缺页中断 / 请求磁盘 I/O</td></tr></tbody></table><h4 id="实时调度" tabindex="-1">实时调度 <a class="header-anchor" href="#实时调度" aria-label="Permalink to &quot;实时调度&quot;">​</a></h4><table tabindex="0"><thead><tr><th>算法</th><th>特点</th></tr></thead><tbody><tr><td><strong>EDF</strong>（最早截止优先）</td><td>动态最优，<strong>强实时首选</strong>，&quot;强实时选 EDF&quot;</td></tr><tr><td><strong>RM</strong>（速率单调）</td><td>静态最优，弱实时可用</td></tr><tr><td><strong>LLF</strong>（最小松弛度）</td><td>动态最优，开销大</td></tr></tbody></table><h4 id="芯片与存储" tabindex="-1">芯片与存储 <a class="header-anchor" href="#芯片与存储" aria-label="Permalink to &quot;芯片与存储&quot;">​</a></h4><table tabindex="0"><thead><tr><th>温度等级</th><th>范围</th></tr></thead><tbody><tr><td>民用/商业级</td><td>0℃～70℃</td></tr><tr><td>工业级</td><td>-40℃～85℃</td></tr><tr><td>军用级</td><td>-55℃～125℃</td></tr></tbody></table><table tabindex="0"><thead><tr><th>ROM 类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>ROM</strong></td><td>掩膜，出厂固定</td></tr><tr><td><strong>PROM</strong></td><td>用户一次性编程（<strong>一次可编程</strong>）</td></tr><tr><td><strong>EPROM</strong></td><td>紫外线擦除</td></tr><tr><td><strong>EEPROM</strong></td><td>电可擦除</td></tr></tbody></table><h4 id="嵌入式系统" tabindex="-1">嵌入式系统 <a class="header-anchor" href="#嵌入式系统" aria-label="Permalink to &quot;嵌入式系统&quot;">​</a></h4><table tabindex="0"><thead><tr><th>知识点</th><th>说明</th></tr></thead><tbody><tr><td>系统调用</td><td>访管中断（陷阱中断），用户态→内核态</td></tr><tr><td>架构模式</td><td>事件驱动 + 数据流架构</td></tr><tr><td>开发方式</td><td><strong>交叉开发</strong>（开发和运行在不同设备）</td></tr><tr><td>M2M 构成</td><td>智能化机器 → M2M 硬件 → 通信网络 → 中间件 → <strong>应用</strong></td></tr><tr><td>DO-178B</td><td>航空适航标准，三要素：<strong>目标 + 过程 + 数据</strong></td></tr></tbody></table><hr><h3 id="二、计算机网络核心公式-★" tabindex="-1">二、计算机网络核心公式 ★ <a class="header-anchor" href="#二、计算机网络核心公式-★" aria-label="Permalink to &quot;二、计算机网络核心公式 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>定理</th><th>公式</th><th>速记</th></tr></thead><tbody><tr><td><strong>奈奎斯特</strong>（无噪声）</td><td>C = 2B · log₂M</td><td>&quot;奈氏 2B·logV&quot;</td></tr><tr><td><strong>香农定理</strong>（有噪声）</td><td>C = B · log₂(1 + S/N)</td><td>&quot;带噪一起涨，速率才上量&quot;</td></tr><tr><td><strong>采样定理</strong></td><td>fs ≥ 2 × fmax</td><td>&quot;至少 2 倍最高频&quot;</td></tr></tbody></table><p><strong>调制解调</strong>：模拟信道传输数字信号（调制=数字→模拟，解调=模拟→数字）。</p><p><strong>通信方式</strong>：半双工 = 1 个逻辑通道；全双工 = 2 个逻辑通道。</p><h4 id="osi-7-层与设备" tabindex="-1">OSI 7 层与设备 <a class="header-anchor" href="#osi-7-层与设备" aria-label="Permalink to &quot;OSI 7 层与设备&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层级</th><th>协议</th><th>设备</th></tr></thead><tbody><tr><td><strong>物理层</strong></td><td>曼彻斯特编码</td><td>集线器、中继器</td></tr><tr><td><strong>数据链路层</strong></td><td>—</td><td><strong>二层交换机</strong>（MAC 地址）、网桥</td></tr><tr><td><strong>网络层</strong></td><td>IP、ICMP、IPSec</td><td><strong>路由器</strong>（IP 地址）、三层交换机</td></tr><tr><td><strong>传输层</strong></td><td>TCP、UDP</td><td>网关（四层交换机）</td></tr><tr><td><strong>应用层</strong></td><td>FTP、SMTP、TELNET、NFS</td><td>—</td></tr></tbody></table><blockquote><p>物理层不提供加密/认证等安全服务。曼彻斯特编码是物理层数字信号编码方式。</p></blockquote><h4 id="局域网特征" tabindex="-1">局域网特征 <a class="header-anchor" href="#局域网特征" aria-label="Permalink to &quot;局域网特征&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td>拓扑</td><td>现代家用/公司局域网普遍采用<strong>星型拓扑</strong></td></tr><tr><td>覆盖范围</td><td>有限（几米到几公里）</td></tr><tr><td>封闭性</td><td>封闭性网络（非开放性）</td></tr><tr><td>传输速率</td><td>高，误码率低</td></tr></tbody></table><hr><h3 id="三、网络安全要点-★" tabindex="-1">三、网络安全要点 ★ <a class="header-anchor" href="#三、网络安全要点-★" aria-label="Permalink to &quot;三、网络安全要点 ★&quot;">​</a></h3><h4 id="_5-类安全服务-osi-标准" tabindex="-1">5 类安全服务（OSI 标准） <a class="header-anchor" href="#_5-类安全服务-osi-标准" aria-label="Permalink to &quot;5 类安全服务（OSI 标准）&quot;">​</a></h4><p><strong>认证、访问控制、数据机密性、数据完整性、不可抵赖性</strong>。</p><h4 id="安全审计-4-要素-gb-t-20945-2007" tabindex="-1">安全审计 4 要素（GB/T 20945-2007） <a class="header-anchor" href="#安全审计-4-要素-gb-t-20945-2007" aria-label="Permalink to &quot;安全审计 4 要素（GB/T 20945-2007）&quot;">​</a></h4><p>控制目标（为什么审）→ 安全漏洞（审什么）→ 控制措施（怎么防）→ 控制测试（怎么测）。</p><h4 id="gb17859-5-级保护-低→高" tabindex="-1">GB17859 5 级保护（低→高） <a class="header-anchor" href="#gb17859-5-级保护-低→高" aria-label="Permalink to &quot;GB17859 5 级保护（低→高）&quot;">​</a></h4><p>用户自主保护 → 系统审计保护 → 安全标记保护 → 结构化保护 → 访问验证保护。</p><h4 id="灾备-6-级" tabindex="-1">灾备 6 级 <a class="header-anchor" href="#灾备-6-级" aria-label="Permalink to &quot;灾备 6 级&quot;">​</a></h4><p>最高级（Level 6）：<strong>数据零丢失（RPO=0）+ 远程集群（RTO≈0）</strong>。</p><h4 id="ssl-tls-提供的服务" tabindex="-1">SSL/TLS 提供的服务 <a class="header-anchor" href="#ssl-tls-提供的服务" aria-label="Permalink to &quot;SSL/TLS 提供的服务&quot;">​</a></h4><table tabindex="0"><thead><tr><th>提供</th><th>不提供</th></tr></thead><tbody><tr><td>保密性（加密）、完整性（MAC）、不可抵赖性（数字证书）</td><td><strong>可用性</strong></td></tr></tbody></table><h4 id="加密算法分类" tabindex="-1">加密算法分类 <a class="header-anchor" href="#加密算法分类" aria-label="Permalink to &quot;加密算法分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对称加密</th><th>非对称加密</th></tr></thead><tbody><tr><td>DES、IDEA、AES、RC5</td><td><strong>RSA</strong>、<strong>ECC</strong>、DSA</td></tr></tbody></table><h4 id="其他安全要点" tabindex="-1">其他安全要点 <a class="header-anchor" href="#其他安全要点" aria-label="Permalink to &quot;其他安全要点&quot;">​</a></h4><table tabindex="0"><thead><tr><th>知识点</th><th>说明</th></tr></thead><tbody><tr><td>SQL 注入防护</td><td>参数化查询、防注入脚本；ORM 使用参数化查询可减少风险</td></tr><tr><td>IPSec</td><td><strong>网络层</strong>安全协议，提供加密、认证、完整性</td></tr><tr><td>MD5</td><td>128 位哈希值，不可逆，但存在<strong>碰撞</strong>（不同输入可产生相同输出）</td></tr><tr><td>TBAC（基于任务访问控制）</td><td>4 组件：工作流、授权结构体、受托人集、许可集</td></tr><tr><td>数据安全治理 3 目标</td><td>满足合规、管理风险、促进数据开发利用</td></tr><tr><td>数据分级分类</td><td>基础安全层（底层）</td></tr></tbody></table><hr><h3 id="四、数据库真题要点" tabindex="-1">四、数据库真题要点 <a class="header-anchor" href="#四、数据库真题要点" aria-label="Permalink to &quot;四、数据库真题要点&quot;">​</a></h3><h4 id="三级模式结构" tabindex="-1">三级模式结构 <a class="header-anchor" href="#三级模式结构" aria-label="Permalink to &quot;三级模式结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>速记</th></tr></thead><tbody><tr><td><strong>外模式</strong></td><td>用户看到的局部数据逻辑结构</td><td>&quot;外看局部&quot;</td></tr><tr><td><strong>概念模式</strong></td><td>全局逻辑结构</td><td>&quot;概看全局&quot;</td></tr><tr><td><strong>内模式</strong></td><td>物理存储结构</td><td>&quot;内看硬盘&quot;</td></tr></tbody></table><h4 id="范式速查" tabindex="-1">范式速查 <a class="header-anchor" href="#范式速查" aria-label="Permalink to &quot;范式速查&quot;">​</a></h4><table tabindex="0"><thead><tr><th>范式</th><th>核心要求</th></tr></thead><tbody><tr><td><strong>1NF</strong></td><td>原子性，列值单一（不要求非空）</td></tr><tr><td><strong>2NF</strong></td><td>消除非主属性对候选键的<strong>部分依赖</strong></td></tr><tr><td><strong>3NF</strong></td><td>消除非主属性对候选键的<strong>传递依赖</strong></td></tr><tr><td><strong>BCNF</strong></td><td>消除主属性对候选键的传递依赖</td></tr><tr><td><strong>4NF</strong></td><td>消除非平凡<strong>多值依赖</strong>（X→→Y 且 X 必须包含码）</td></tr></tbody></table><h4 id="关系代数" tabindex="-1">关系代数 <a class="header-anchor" href="#关系代数" aria-label="Permalink to &quot;关系代数&quot;">​</a></h4><table tabindex="0"><thead><tr><th>运算</th><th>说明</th></tr></thead><tbody><tr><td>基本运算</td><td>选择（σ）、投影（π）、连接（⋈）、差（-）、并（∪）、笛卡尔积（×）</td></tr><tr><td>非基本运算</td><td>删除（Delete）不属于关系代数基本运算</td></tr><tr><td>笛卡尔积</td><td>R × S 结果元组数 = n × m</td></tr><tr><td>交集</td><td>R ∩ S = R - (R - S)</td></tr><tr><td>自然连接</td><td>同名属性等值连接 + <strong>去重</strong>保留一份同名列</td></tr></tbody></table><h4 id="其他数据库要点" tabindex="-1">其他数据库要点 <a class="header-anchor" href="#其他数据库要点" aria-label="Permalink to &quot;其他数据库要点&quot;">​</a></h4><table tabindex="0"><thead><tr><th>知识点</th><th>说明</th></tr></thead><tbody><tr><td>ACID</td><td>原子性/一致性/隔离性/持久性（<strong>并发性不是</strong>事务特性）</td></tr><tr><td>反规范化</td><td><strong>物理设计阶段</strong>，引入冗余减少表连接提高查询性能</td></tr><tr><td>用户定义完整性</td><td>CHECK 约束（如性别仅&quot;男&quot;/&quot;女&quot;）</td></tr><tr><td>候选码</td><td>能唯一标识元组的<strong>最小</strong>属性集</td></tr></tbody></table>',56)])])}const q=d(e,[["render",h]]);export{u as __pageData,q as default};
